/**
 * Shapes mirroring the Rust core in `src-tauri`.
 *
 * These are hand-written for now and are REPLACED WHOLESALE by
 * `src/bindings.ts`, generated by tauri-specta, the moment the Rust
 * commands land in M1. Nothing here may become a second source of truth:
 * the colour maths lives in Rust because the effect has to hold with no
 * window open, and the UI only ever renders what the core reports.
 */

export type ChannelId =
  | "vibrance"
  | "saturation"
  | "hue"
  | "brightness"
  | "contrast"
  | "gamma"
  | "temperature"
  | "tint";

/** Which stage of the fixed device path carries a channel. */
export type Stage = "matrix" | "lut";

/**
 * How faithfully a backend can express a channel. Deliberately not a
 * boolean: vibrance is genuinely approximate on both vendor-neutral
 * backends and the interface has to be able to say so.
 */
export type Fidelity = "exact" | "approximate" | "clamped" | "inert" | "unrealised";

export interface Channel {
  id: ChannelId;
  /** Fixed-width key. The field is a table; keys must not vary in width. */
  key: string;
  name: string;
  min: number;
  max: number;
  neutral: number;
  step: number;
  unit: "percent" | "degrees" | "factor";
  stage: Stage;
  fidelity: Fidelity;
  /** Present only when fidelity is not `exact`; states the machine fact. */
  note?: string;
}

