export type ColorState = Record<ChannelId, number>;

export const NEUTRAL: ColorState = CHANNELS.reduce((acc, c) => {
  acc[c.id] = c.neutral;
  return acc;
}, {} as ColorState);

export function formatValue(channel: Channel, raw: number): string {
  switch (channel.unit) {
    case "degrees":
      return `${raw > 0 ? "+" : ""}${raw}°`;
    case "factor":
      return (raw / 100).toFixed(2);
    case "percent":
      return channel.neutral === 0
        ? `${raw > 0 ? "+" : ""}${raw}%`
        : `${raw}%`;
  }
}

/** True when a channel is doing nothing to the screen right now. */
export function isInert(fidelity: Fidelity): boolean {
  return fidelity === "inert" || fidelity === "unrealised";
}

export const FIDELITY_LABEL: Record<Fidelity, string> = {
  exact: "EXACT",
  approximate: "APPROX",
  clamped: "CLAMPED",
  inert: "INERT",
  unrealised: "NO PATH",
};

// ── Session state ───────────────────────────────────────────────────────

export type ActivationMode = "focused" | "running" | "manual";
export type MatchKind = "full path" | "package" | "exe name";

export interface Preset {
  id: string;
  name: string;
  /** null for the desktop default, which binds to nothing. */
  exe: string | null;
  mode: ActivationMode;
  state: ColorState;
}

export interface DisplayInfo {
  key: string;
  name: string;
  primary: boolean;
  hdr: boolean;
}

export interface SessionState {
  enabled: boolean;
  activePresetId: string;
  matchedBy: MatchKind | null;
  exclusiveFullscreen: boolean;
  displays: DisplayInfo[];
  gammaRangeUnlocked: boolean;
}
